/* crosswalk cards, r47. */
(window.LADDER_CARDS=window.LADDER_CARDS||{})["47a"]=[{"q": "Two arrows 1 and 1′ at A both do nothing. Which technique makes them one arrow?", "a": "one-do-nothing", "w": ["one-undoing", "order-category", "matched-to-matched"], "why": "1 = 1 ∘ 1′ = 1′, each technique used once."}, {"q": "An arrow f has undoings g and h. Which technique gives g = h?", "a": "one-undoing", "w": ["one-do-nothing", "natural-undo", "one-matching"], "why": "g = g ∘ (f ∘ h) = (g ∘ f) ∘ h = h."}, {"q": "A relation on a set makes a category, one arrow for each related pair, exactly when it is…", "a": "reflexive and transitive", "w": ["symmetric and transitive", "reflexive and symmetric", "a sameness relation"], "why": "Do-nothing arrows need reflexive; running in a row needs transitive."}, {"q": "A group seen as a category has how many things?", "a": "one", "w": ["one for each member", "two", "none"], "why": "The members are the arrows from the one thing to itself; running in a row is the product."}, {"q": "In an order seen as a category, how many arrows run from x to y at most?", "a": "one", "w": ["two", "as many as members between them", "none"], "why": "An arrow is the fact x ≤ y, and there is one fact or none."}, {"q": "Two things A and B are matched, A ≅ B, when…", "a": "some arrow A → B can be undone", "w": ["there is an arrow each way", "they have the same members", "they are equal"], "why": "An undoing g with g ∘ f and f ∘ g the do-nothing arrows."}, {"q": "In the category of sets, which arrows can be undone?", "a": "the matchings", "w": ["the one-to-one maps", "the onto maps", "every map"], "why": "A function has a two-sided undoing exactly when it is a matching."}, {"q": "Being matched is a sameness relation. Which step shows it is symmetric?", "a": "the undoing of f is undone by f", "w": ["f ∘ f is the do-nothing arrow", "every arrow can be undone", "matched things are equal"], "why": "If g undoes f then f undoes g; transitive by running undoings in the reverse row."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["47b"]=[{"q": "A map of categories F has A ≅ B. Which technique gives F(A) ≅ F(B)?", "a": "matched-to-matched", "w": ["turned-round", "letter-by-letter", "one-undoing"], "why": "F(g) undoes F(f), since F keeps rows and do-nothing arrows."}, {"q": "Loops make a map of categories from pointed spaces to groups. What does that give about the circle and the disc?", "a": "they are not matched, since their loop groups ℤ and 1 are not", "w": ["they are matched", "the disc has loop group ℤ", "nothing, loops are not kept"], "why": "Matched things go to matched things; turned round, unmatched values mean unmatched things."}, {"q": "A map out of the free group on letters is fixed by where the letters go. Which technique?", "a": "letter-by-letter", "w": ["matched-to-matched", "turned-round", "free-forgetful"], "why": "Every member is a row of letters and undoings, and a product-keeping map follows the row."}, {"q": "Readings V ↦ V* send f : V → W to which arrow?", "a": "f* : W* → V*, the reading φ to φ ∘ f", "w": ["f* : V* → W*", "f itself", "the undoing of f"], "why": "The arrow turns round; this is the turned-round technique."}, {"q": "A map of categories with arrows turned round keeps which technique in which form?", "a": "(g ∘ f)* = f* ∘ g*", "w": ["(g ∘ f)* = g* ∘ f*", "(g ∘ f)* = g ∘ f", "(g ∘ f)* = 1"], "why": "Reading φ ∘ g ∘ f two ways."}, {"q": "Forgetting from groups to sets sends a product-keeping map to…", "a": "the same function, read on members", "w": ["its kernel", "the free group on its members", "nothing"], "why": "Rows and do-nothing maps are kept at once."}, {"q": "A map of categories carries a number to each thing. What does matched-to-matched make of that number?", "a": "a value every matching keeps", "w": ["a value no matching keeps", "an arrow", "a category"], "why": "Unmatched values prove unmatched things; equal values prove nothing."}, {"q": "A map of categories must keep which two techniques?", "a": "rows of arrows and do-nothing arrows", "w": ["sums and products", "undoings and sums", "only rows of arrows"], "why": "F(g ∘ f) = F(g) ∘ F(f) and F(1_A) = 1_{F(A)}."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["47c"]=[{"q": "Natural maps α : F ⇒ G and β : G ⇒ H. Which technique makes β ∘ α natural?", "a": "square-in-a-row", "w": ["natural-undo", "double-reading", "matched-to-matched"], "why": "Two closed squares side by side close the outer square."}, {"q": "For V of finite dimension, ev : V → V** with ev(v)(φ) = φ(v) is a natural matching. Which technique?", "a": "double-reading", "w": ["no-chosen-reading", "reading-basis", "natural-undo"], "why": "ev is defined with no choice; a basis is used only to prove it one-to-one."}, {"q": "Over a field with more than three members, no family V ≅ V* is carried along by every matching. Which technique?", "a": "no-chosen-reading", "w": ["double-reading", "natural-undo", "turned-round"], "why": "The stretch x ↦ tx with t² ≠ 1 breaks the square."}, {"q": "A natural map whose every arrow can be undone. Which technique makes the undoings natural?", "a": "natural-undo", "w": ["square-in-a-row", "one-undoing", "matched-to-matched"], "why": "Pre- and post-compose the closed square with the undoings."}, {"q": "A family of arrows α_A : F(A) → G(A) is natural when…", "a": "G(f) ∘ α_A = α_B ∘ F(f) for every f : A → B", "w": ["each α_A can be undone", "α_A = α_B for all A, B", "F = G"], "why": "Every square closes."}, {"q": "Why does the proof of no-chosen-reading need more than three members?", "a": "it needs t with t² ≠ 1", "w": ["it needs t ≠ 0", "fields with 3 members have no stretches", "the dimension must be 3"], "why": "Over 2 or 3 members every nonzero t has t² = 1; those fields break later in dimension, by count."}, {"q": "Over ℤ, A has rows (3, 5) and (1, 4), det 7. On the clock of 5 its image has det 2. Which fact does this check?", "a": "det is natural from GL₂ to the units: the square closes for the ring map ℤ → ℤ/5", "w": ["det can be undone", "V ≅ V** naturally", "no family V ≅ V* is natural"], "why": "det is a sum of products, and ring maps keep sums and products."}, {"q": "In V ↦ V**, which line of the proof uses a basis?", "a": "that ev is one-to-one, so a matching", "w": ["that ev is defined", "that ev is straight", "that ev is natural"], "why": "A basis proves; it never defines."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["47d"]=[{"q": "A × B with the two projections is a product in Set. Which technique?", "a": "pair-map", "w": ["cases-map", "one-matching", "equal-pairs"], "why": "z ↦ (f(z), g(z)) is the one map through which f, g run."}, {"q": "Two products of A and B are matched by exactly one arrow that agrees with the projections. Which technique?", "a": "one-matching", "w": ["pair-map", "one-undoing", "known-by-arrows"], "why": "Each runs through the other; the round trip agrees, so it is the do-nothing arrow."}, {"q": "The sum of A and B in Set, with the two insertions, is licensed by which technique?", "a": "cases-map", "w": ["pair-map", "one-matching", "classes-force"], "why": "Define the map out by cases on which part a member is from."}, {"q": "In an order seen as a category, what is the product of x and y?", "a": "their greatest lower bound", "w": ["their least upper bound", "x", "their sum as numbers"], "why": "An arrow to both is a lower bound; running through means below the meet."}, {"q": "A sum is the same as a product with what changed?", "a": "every arrow turned round", "w": ["every thing doubled", "the do-nothing arrows removed", "the projections undone"], "why": "Insertions into the sum, and one map out."}, {"q": "Two rivals for the product of A and B, P and Q. Which statement does one-matching NOT give?", "a": "P and Q are equal sets", "w": ["P ≅ Q", "the matching agrees with the projections", "only one matching agrees"], "why": "Arrows fix up to one matching, never which set."}, {"q": "Among statements ordered by ⇒, what is the sum of P and Q?", "a": "P ∨ Q", "w": ["P ∧ Q", "P ⇒ Q", "¬P"], "why": "Arrows into R from P and from Q are one arrow from P ∨ Q."}, {"q": "In parts of a set ordered by ⊆, what is the product of two parts?", "a": "their common part", "w": ["their union", "the whole set", "the empty part"], "why": "The biggest part inside both."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["47e"]=[{"q": "The sift {x ∈ A : f(x) = g(x)} is the limit of the two arrows f, g : A → B. Which technique?", "a": "sift-meets", "w": ["classes-force", "glued-is-colimit", "pair-map"], "why": "A map that makes f and g agree lands in the sift, one way."}, {"q": "The set of classes of a sameness relation is a colimit. Which technique?", "a": "classes-force", "w": ["sift-meets", "well-defined-function", "cases-map"], "why": "A map that agrees on related members runs through the classes in exactly one way."}, {"q": "Gluing two spaces along a common part is a colimit in Top. Which technique?", "a": "glued-is-colimit", "w": ["glued-map", "classes-force", "sift-meets"], "why": "A map out of the glued space is a pair of maps that agree."}, {"q": "A continuous map out of a glued space amounts to…", "a": "a pair of continuous maps on the pieces that agree on the common part", "w": ["one map on either piece", "a map into the common part", "nothing more than a function"], "why": "The glued-is-colimit technique."}, {"q": "A limit of a picture is…", "a": "a thing with arrows to the picture through which every rival runs in exactly one way", "w": ["the biggest thing in the picture", "a sum of the picture", "the picture's do-nothing arrows"], "why": "Products and sifts are limits of particular pictures."}, {"q": "Any two limits of one picture are…", "a": "matched by exactly one arrow that agrees", "w": ["equal", "unmatched", "matched in many ways"], "why": "one-matching, read for any picture."}, {"q": "The product of A and B is the limit of which picture?", "a": "two things, no arrows", "w": ["one thing", "two parallel arrows", "an arrow A → B"], "why": "The sift needs two parallel arrows; a product needs none."}, {"q": "What is the colimit of the empty picture in Set?", "a": "the empty set", "w": ["a one-member set", "every set", "none exists"], "why": "One map out of ∅ to every set."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["47f"]=[{"q": "Maps from the free group on X to G match the functions from X to the members of G. Which technique?", "a": "free-forgetful", "w": ["letter-by-letter", "pair-to-function", "fixing"], "why": "Freeing is left of forgetting; the matching is natural in X and G."}, {"q": "Functions A × B → C match functions A → C^B. Which technique?", "a": "pair-to-function", "w": ["free-forgetful", "pair-map", "left-keeps-sums"], "why": "f ↦ (a ↦ (b ↦ f(a, b)))."}, {"q": "Any relation between two sets gives a correspondence between parts with fixed parts matched. Which technique?", "a": "fixing", "w": ["free-forgetful", "known-by-arrows", "one-matching"], "why": "An adjunction between two orders of parts."}, {"q": "A left map of an adjunction carries sums to sums. Which technique?", "a": "left-keeps-sums", "w": ["cases-map", "free-forgetful", "matched-to-matched"], "why": "Arrows out of F(sum) match arrows out of the sum into U(B), which are pairs."}, {"q": "How many product-keeping maps run from the free group on two letters to S₃?", "a": "36", "w": ["6", "12", "9"], "why": "6 choices for each letter."}, {"q": "How many functions run from {1,2} × {1,2,3} to {0,1}, the count the pair-to-function technique also gives for {1,2} → ({1,2,3} → {0,1})?", "a": "64", "w": ["36", "12", "8"], "why": "2⁶ = (2³)²."}, {"q": "By left-keeps-sums, the free group on the empty set of letters is…", "a": "the group with one member", "w": ["ℤ", "the empty set", "S₃"], "why": "The sum of nothing goes to the sum of nothing, which in groups is the trivial group."}, {"q": "An adjunction F ⊣ U matches…", "a": "arrows F(A) → B with arrows A → U(B), naturally", "w": ["F(A) with U(B)", "arrows A → B with F(A) → U(B)", "things with arrows"], "why": "Naturally in both A and B."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["47g"]=[{"q": "Natural maps from h_A to F match the members of F(A). Which technique?", "a": "arrows-into", "w": ["known-by-arrows", "arrows-from-one", "natural-undo"], "why": "α is fixed by α_A(1_A), and any member u gives α_B(f) = F(f)(u)."}, {"q": "h_A ≅ h_B naturally gives A ≅ B. Which technique?", "a": "known-by-arrows", "w": ["arrows-into", "one-matching", "matched-to-matched"], "why": "The matching comes from one arrow each way, fixed by the do-nothing arrows."}, {"q": "Product-keeping maps ℤ → G match members of G. Which technique?", "a": "arrows-from-one", "w": ["arrows-into", "free-forgetful", "letter-by-letter"], "why": "A map from ℤ is fixed by where 1 goes."}, {"q": "Why is the do-nothing arrow of A enough to fix a natural α : h_A ⇒ F?", "a": "every f : B → A is h_A(f)(1_A), and naturality carries 1_A to f", "w": ["the category has one thing", "α can be undone", "F keeps sums"], "why": "α_B(f) = F(f)(α_A(1_A))."}, {"q": "In the order of the line, the arrows into √2 from the fractions are…", "a": "its cut, the fractions below it", "w": ["the fraction nearest it", "no arrows", "all fractions"], "why": "A thing is known by the arrows into it."}, {"q": "A group G as a one-thing category: natural maps from h_⋆ to itself match…", "a": "the members of G", "w": ["the arrows of Set", "the subgroups of G", "nothing"], "why": "arrows-into with F = h_⋆ itself."}, {"q": "Which statement follows from known-by-arrows?", "a": "two products of A and B are matched", "w": ["two products of A and B are equal", "every thing is a set of arrows", "every natural map can be undone"], "why": "Arrows into a product are pairs of arrows; both rivals have them."}, {"q": "h_A sends a thing B to…", "a": "the arrows from B into A", "w": ["the arrows from A into B", "A itself", "B itself"], "why": "Arrows into A, turned round in B."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["47h"]=[{"q": "V ⊗ W exists, with basis eᵢ ⊗ f_j and dimension mn. Which technique?", "a": "grid-space", "w": ["fewest-terms", "two-slot", "coprime-clocks"], "why": "Build the grid of pairs of basis members and check the universal property."}, {"q": "A grid of rank 1 is a single product v ⊗ w. Which technique?", "a": "fewest-terms", "w": ["grid-space", "coprime-clocks", "one-matching"], "why": "The fewest terms of a member is the rank of its grid of numbers."}, {"q": "ℤ/m ⊗ ℤ/n is nothing when gcd(m, n) = 1. Which technique?", "a": "coprime-clocks", "w": ["grid-space", "fewest-terms", "count-the-arrows"], "why": "1 = am + bn, so x ⊗ y = (am + bn)(x ⊗ y) = 0."}, {"q": "What is the dimension of ℝ² ⊗ ℝ³?", "a": "6", "w": ["5", "3", "8"], "why": "Dimensions multiply; 5 is the product, ℝ² × ℝ³."}, {"q": "Why is e₁ ⊗ f₁ + e₂ ⊗ f₂ no single v ⊗ w?", "a": "its grid is the do-nothing grid of rank 2", "w": ["it has two terms", "e₁ and e₂ are unmatched", "it is nothing"], "why": "A single product has a grid of rank at most 1."}, {"q": "The tensor product is pinned down by which maps?", "a": "maps straight in each slot", "w": ["straight maps", "all functions", "product-keeping maps"], "why": "A map straight in each slot out of V × W is one straight map out of V ⊗ W."}, {"q": "0 → ℤ → ℤ → ℤ/2 → 0, the middle map doubling, is exact. Tensored with ℤ/2, what fails?", "a": "the first map is no longer one-to-one", "w": ["the last map is no longer onto", "nothing fails", "the row is not defined"], "why": "Doubling on ℤ/2 is 0."}, {"q": "Physics calls members of a tensor product of more than one term entangled. In the ladder's words they are…", "a": "members not a single product v ⊗ w", "w": ["members that are nothing", "members of V × W", "straight maps"], "why": "fewest-terms counts the terms."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["47i"]=[{"q": "In the dividing order on the counting numbers, the product of 12 and 18 is…", "a": "6", "w": ["36", "216", "1"], "why": "The greatest common divisor; the sum is the lcm, 36."}, {"q": "The product in the dividing order is the greatest common divisor. Which technique?", "a": "divides-order", "w": ["count-the-arrows", "one-matching", "no-common-field"], "why": "A rival divides both, so divides the gcd."}, {"q": "Counting maps into a test thing tells two guesses apart. Which technique?", "a": "count-the-arrows", "w": ["divides-order", "arrows-into", "one-matching"], "why": "Matched things have matched sets of arrows into any test thing."}, {"q": "Product-keeping maps from ℤ × ℤ to S₃ number 18; from the sum of ℤ and ℤ, 36. What does this prove?", "a": "ℤ × ℤ is not the sum of ℤ and ℤ in groups", "w": ["ℤ × ℤ is the sum", "S₃ is turn-about", "the counts prove nothing"], "why": "A sum would have 6 · 6 = 36 maps out to S₃."}, {"q": "Why only 18 maps from ℤ × ℤ to S₃?", "a": "the two images must commute", "w": ["S₃ has 18 members", "the maps must be onto", "ℤ × ℤ has 18 members"], "why": "Pairs of members of S₃ that commute: 18."}, {"q": "Fields of different characteristic, such as the rationals and the clock of 2, have no product. Which technique?", "a": "no-common-field", "w": ["count-the-arrows", "divides-order", "coprime-clocks"], "why": "A field mapping to both would have 1 + 1 = 0 and 1 + 1 ≠ 0."}, {"q": "Why can a field map from P to two fields fail to exist?", "a": "maps of fields keep 1 + 1 and so the count to 0", "w": ["fields have no arrows", "every field map is a matching", "products of fields are rings"], "why": "Field maps are one-to-one and keep the characteristic."}, {"q": "In groups, the sum of two things is…", "a": "the free product, not the pair group", "w": ["the pair group", "the common part", "the trivial group"], "why": "Its maps out are any pair of maps."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["47j"]=[{"q": "Each typed term has one type, read from its build. Which technique?", "a": "typed-term", "w": ["proofs-as-terms", "detour-is-step", "pair-to-function"], "why": "Each technique builds one type from the types of its parts."}, {"q": "Tree proofs of A ⇒ B match typed terms of type A → B. Which technique?", "a": "proofs-as-terms", "w": ["typed-term", "detour-cut", "free-forgetful"], "why": "Assumptions are variables, ⇒-in is a function, ⇒-out is applying it."}, {"q": "Cutting a detour from a proof is one step of running its program. Which technique?", "a": "detour-is-step", "w": ["detour-cut", "proofs-as-terms", "typed-term"], "why": "(λx. t) u becomes t with u for x."}, {"q": "Why does P ∨ ¬P have no closed term?", "a": "a term of it would choose a side with no information", "w": ["it is false", "P has no type", "¬P has no meaning"], "why": "A closed term of a sum type is an insertion of one side, so it would prove P or ¬P outright."}, {"q": "A pair type A × B corresponds to which connective?", "a": "and", "w": ["or", "implies", "not"], "why": "A term of A × B is a pair of terms."}, {"q": "A function type A → B corresponds to…", "a": "implies", "w": ["and", "or", "not"], "why": "A term of A → B turns a proof of A into one of B."}, {"q": "Which statement is held in trust on 47j?", "a": "that typed programs all stop", "w": ["that every term has a type", "that detours can be cut", "that proofs are trees"], "why": "The stopping proof is not given on the page."}, {"q": "Currying A × B → C as A → (B → C) is, as proofs, which move?", "a": "from A ∧ B ⇒ C to A ⇒ (B ⇒ C)", "w": ["from A ∨ B to B ∨ A", "from A to ¬¬A", "from A ⇒ B to B ⇒ A"], "why": "The pair-to-function technique read as a proof."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["47·cb0"]=[{"q": "A matching A ≅ B gives matchings of the arrows into A with the arrows into B, for every test thing. Which technique?", "a": "arrow-counts-kept", "w": ["first-run", "known-by-arrows", "one-matching"], "why": "Compose with the matching and its undoing."}, {"q": "How does arrow-counts-kept tell ℤ/6 from S₃?", "a": "counting product-keeping maps from a test group", "w": ["they have different numbers of members", "by their names", "it cannot"], "why": "Both have 6 members; maps out of ℤ × ℤ, for one, count differently."}, {"q": "Any two things that run as counting numbers, with a start and a next, are matched in exactly one way. Which technique?", "a": "first-run", "w": ["arrow-counts-kept", "recursion", "matching-worlds"], "why": "The recursion of rung 9 builds the map each way."}, {"q": "Which set is three? The page's answer is…", "a": "any thing in the third place of a run; no one set", "w": ["{0, 1, 2}", "{{{∅}}}", "3c's 3 only"], "why": "Matched runs agree on everything said with arrows."}, {"q": "Rung 0's sameness of a thing with itself sits beside matching how?", "a": "sameness gives the do-nothing matching; matching is sameness up to a choice of arrow", "w": ["they are the same relation", "matching is stronger", "neither is a sameness relation"], "why": "Every equality gives a matching, not the reverse."}, {"q": "In first-run, the map from one run to another, start to start and next to next, is built by which technique?", "a": "recursion", "w": ["arrow-counts-kept", "matching-worlds", "one-undoing"], "why": "Rung 9's recursion fixes a map by its start and its next."}, {"q": "Two builds of the counting numbers agree on which statements?", "a": "those made with zero, next and arrows", "w": ["all statements, including membership", "none", "only those about 3"], "why": "Is 1 a member of 3 is not one of them."}, {"q": "Which question of rung 3 does 47·cb0 answer?", "a": "which set is three", "w": ["whether 3 is prime", "whether 3 = 2 + 1", "how many sets there are"], "why": "3c.4.4."}];

(window.LADDER_CARDS=window.LADDER_CARDS||{})["47·phys"]=[{"q": "On a cut facing n, what does mᵀσn give?", "a": "the push along m on that cut", "w": ["the push across n alone", "the area of the cut", "the turn of σ"], "why": "The face-and-axis technique."}, {"q": "What does uᵀΘu give, for u of length 1?", "a": "the rotational inertia about the axis along u", "w": ["the spin about u", "the energy of any turning", "the turn of Θ"], "why": "Σ m(|r|² − (r·u)²) = Σ mρ²."}, {"q": "The axes turn to the columns of a length-keeper Q. What is a vector's new list?", "a": "Qᵀx", "w": ["Qx", "QxQᵀ", "x, unchanged"], "why": "x = Qx′, and Qᵀ undoes Q."}, {"q": "The axes turn to the columns of Q. What is the new grid of a reading of two vectors?", "a": "QᵀGQ", "w": ["QGQᵀ", "QG", "G, unchanged"], "why": "The new-axes technique."}, {"q": "Pure shear τ, on axes turned by 45°, becomes which grid?", "a": "a pull τ and a push τ, no shear", "w": ["pure shear 2τ", "a pull τ along both axes", "0"], "why": "QᵀσQ = diag(τ, −τ)."}, {"q": "Which technique says the technique QᵀGQ is forced, not chosen?", "a": "square-the-space", "w": ["face-and-axis", "same-on-every-axes", "grid-space"], "why": "V ↦ V ⊗ V, f ↦ f ⊗ f is a map of categories."}, {"q": "What does every choice of axes agree on, for a reading of two vectors?", "a": "its stretches and its rank", "w": ["every number of its grid", "its top left number", "its corner numbers"], "why": "The same-on-every-axes technique."}, {"q": "Why is a pure shear no single pull, on any axes?", "a": "its rank is 2", "w": ["its stretches are equal", "its grid is symmetric", "its corner numbers are equal"], "why": "Fewest-terms (47h2) with rank kept."}, {"q": "“The stress has 1 in the top left on any axes.” What is wrong?", "a": "a quarter turn moves the 1 to the bottom right", "w": ["nothing: it is a tensor", "stress grids have no top left", "it holds only for still water"], "why": "It breaks the new-axes technique."}, {"q": "Which stress looks the same on every axes?", "a": "a straight push p every way, pI", "w": ["pure shear", "a single pull", "none"], "why": "QᵀpIQ = pI."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["47·eng"]=[{"q": "Two parts with transfers H₁ and H₂ in a row. What is the whole?", "a": "H₂H₁", "w": ["H₁ + H₂", "H₁/H₂", "H₁ ⊕ H₂"], "why": "The row-of-boxes technique."}, {"q": "Two parts f and g side by side, on lists. What is the grid?", "a": "f's grid top left, g's bottom right, 0 in the corners", "w": ["f's grid times g's", "f's grid plus g's", "one grid with f and g in each block"], "why": "Side by side is the product of pairs."}, {"q": "Which line is the box-drawing technique?", "a": "(g ∘ f) ⊕ (g′ ∘ f′) = (g ⊕ g′) ∘ (f ⊕ f′)", "w": ["g ∘ f = f ∘ g", "f ⊕ g = g ⊕ f", "(g ∘ f) ⊕ f′ = g ∘ (f ⊕ f′)"], "why": "A drawing read by rows or by columns."}, {"q": "Two quantum gates side by side. What does side by side mean there?", "a": "the tensor product, U ⊗ V", "w": ["the product of pairs, U ⊕ V", "U times V", "U plus V"], "why": "Joint states live in 47h's tensor product."}, {"q": "A part G with H fed back and taken from the input. What is the whole?", "a": "G/(1 + GH)", "w": ["G − H", "GH", "G/(1 − GH)"], "why": "y = G(u − Hy)."}, {"q": "G = 100 000 and H = 0.01. About what is the whole?", "a": "100", "w": ["100 000", "1000", "0.01"], "why": "Near 1/H for GH large."}, {"q": "Two halving dividers of equal resistors in a row send V to what?", "a": "V/5", "w": ["V/4", "V/2", "V/3"], "why": "The loading technique."}, {"q": "Why do the two dividers not give a quarter?", "a": "the second draws current from the first", "w": ["resistors age", "the first divider is not a part", "voltages do not multiply"], "why": "A part is an arrow on voltages only while nothing is drawn."}, {"q": "What is the chain grid of a resistor R along the path?", "a": "rows (1, R) and (0, 1)", "w": ["rows (1, 0) and (1/R, 1)", "rows (R, 0) and (0, R)", "rows (1, 1) and (0, R)"], "why": "Same current, voltage up by RI."}, {"q": "Three halving dividers in a row, by chain grids. The far voltage?", "a": "V/13", "w": ["V/8", "V/9", "V/6"], "why": "D³ has top left 13."}];
/* phase F und_r47: understanding cards, appended (ids follow the deck's own) */
(window.LADDER_CARDS["47a"]=window.LADDER_CARDS["47a"]||[]).push(
 {"u":"47a1.1","q":"What four things make a category, and which two techniques must they keep? Why is a proof that uses only those two techniques a proof for sets, groups and spaces at once?","a":"A collection of things; for any two things A and B a collection of arrows from A to B; for arrows f : A → B and g : B → D an arrow g ∘ f : A → D; and for each thing A an arrow id_A; the techniques are h ∘ (g ∘ f) = (h ∘ g) ∘ f and f ∘ id_A = f = id_B ∘ f; sets with functions, groups with product-keeping maps and spaces with continuous maps are all categories, so what follows from the two techniques alone holds in each","w":["Sets, functions, members and products; the techniques are that arrows are one-to-one and onto; the proof works because groups and spaces are sets","Things, arrows, undoings and a product; the techniques are that every arrow can be undone and arrows commute; the proof works because all three are groups","Things and arrows only; the one technique is g ∘ f = f ∘ g; a proof must still be redone for each category"],"why":"The one-do-nothing proof is 19b1’s, with “member” turned into “arrow”."},
 {"u":"47a2.1","q":"How is a group a category with one thing, and what are its arrows? What does the order-category technique say, and which technique of a category needs the relation to be transitive?","a":"Take one thing ⋆ and let the arrows ⋆ → ⋆ be the members of G, with g after h the product g h and the do-nothing arrow the member that does nothing; a relation on a set makes a category, with one arrow from x to y exactly when x is related to y, exactly when the relation is reflexive and transitive; an arrow x → y and one y → z need an arrow x → z, which is transitive, and id_x needs x ≤ x, which is reflexive","w":["The things are the members and the arrows the products; a relation makes a category when it is symmetric; the do-nothing technique needs transitive","The one thing is the identity and there are no arrows; every relation makes a category; no technique needs transitive","The things are the part-groups; a relation makes a category when it keeps things apart; the brackets technique needs reflexive"],"why":"A category is a group spread out over many things."},
 {"u":"47a3.1","q":"When is an arrow undoable, and when are two things matched? Why is t ↦ (cos 2πt, sin 2πt) undoable in Set and not in Top?","a":"f : A → B is undoable when some g : B → A has g ∘ f = id_A and f ∘ g = id_B, and then A and B are matched; the map from [0, 1) onto the circle is one-to-one and onto, so its undoing exists as a function, but the backwards map is not continuous at (1, 0), so it is no arrow of Top","w":["When it is one-to-one; things are matched when they have an arrow between them; the map is not undoable in Set because [0, 1) is not closed","When g ∘ f = id_A alone; things are matched when they are equal; the map is undoable in both categories","When it is onto; the map is undoable in Top and not in Set, since Set has no continuous maps"],"why":"Sameness, in a category, belongs to the arrows."},
 {"u":"47a4.1","q":"Why may g ∘ f not be written for f : A → B and g : C → D with B and C different? Why is an arrow of a category not always a function?","a":"An arrow runs in a row only from where the last one ended, so g ∘ f needs B to be C; and in an order an arrow is only the fact x ≤ y, and in a one-thing group it is a member","w":["It may be written always; and every arrow is a function","Because g must be undoable; and arrows are always members of a group","Because A and D differ; and an arrow is a function only in an order"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["47b"]=window.LADDER_CARDS["47b"]||[]).push(
 {"u":"47b1.1","q":"What must a map of categories F do with things, with arrows, with g ∘ f and with id_A? What does the matched-to-matched technique say, and how does it tell the circle from a disc?","a":"It gives each thing A a thing F(A) and each arrow f : A → B an arrow F(f) : F(A) → F(B), with F(g ∘ f) = F(g) ∘ F(f) and F(id_A) = id_F(A); a map of categories carries an undoable arrow to an undoable arrow, so matched things to matched things; the loop group of the circle is ℤ and that of a disc has one member, and these are not matched, so the circle and the disc are not the same shape","w":["It sends things to arrows and arrows to things; it carries matched things to unmatched ones; the circle and disc have the same loop group","It keeps things and drops arrows; if F(A) ≅ F(B) then A ≅ B; the circle and the disc both have loop group ℤ, so they match","It sends g ∘ f to F(f) ∘ F(g); it carries every arrow to an undoable one; the disc has a larger loop group than the circle"],"why":"Read as the contrapositive: unmatched values, unmatched things."},
 {"u":"47b2.1","q":"What does forgetting do to a group and to a product-keeping map, and what does freeing do to a set and to a function? What does the letter-by-letter technique say, and which word in the presented-map technique gives F(k ∘ h) = F(k) ∘ F(h)?","a":"Forgetting sends a group to its set of members and a product-keeping map to the same function, the products forgotten; freeing sends a set S to the free group on the letters S and a function h to the map that writes h(s) for each letter s; a function h from S to T gives exactly one product-keeping map F(h) sending each letter s to h(s), and F(k ∘ h) = F(k) ∘ F(h); the words “exactly one” give it: two maps that agree on the letters are one map","w":["Forgetting sends a group to its identity; freeing sends a set to its count; the technique says F(h) is any map at all, and “relations” gives the technique","Forgetting sends a set to a group; freeing sends a group to its members; the technique says there are many maps F(h), and “letters” gives the technique","Forgetting drops the members; freeing adds relations; the technique says F(h) is one-to-one, and “reduced” gives the technique"],"why":"Freeing builds the most general thing; forgetting throws the structure away."},
 {"u":"47b3.1","q":"What is f* for a linear map f : V → W, and in which direction does it run? What does the turned-round technique say, and which step of rung 19 has the same shape?","a":"f*(r) = r ∘ f: a reading of W, taken after f, is a reading of V, so f* runs back, from W* to V*; readings turn arrows round, and (g ∘ f)* = f* ∘ g*; that is 19c1’s socks and shoes, (h g)⁻¹ = g⁻¹ h⁻¹","w":["f*(r) = f ∘ r, from V* to W*; (g ∘ f)* = g* ∘ f*; the same shape as 19b1’s one identity","f* is the undoing of f, from W to V; (g ∘ f)* = g ∘ f; the same shape as 19d’s part-divides-whole","f* is f read twice, from V to W; readings keep the order; the same shape as 19a’s brackets technique"],"why":"A map that turns arrows round is a map from the category turned round."},
 {"u":"47b4.1","q":"Why does F(A) ≅ F(B) not give A ≅ B? Why can (g ∘ f)* not be g* ∘ f*?","a":"The technique runs one way: S₃ and ℤ/6 both forget to sets of six members, matched as sets, and are not matched as groups; and g* starts at W* and f* ends at U*, so g* ∘ f* does not even meet end to start","w":["It does give A ≅ B; and (g ∘ f)* is g* ∘ f*","Because F is never one-to-one; and g* is not linear","Because sets cannot be matched; and f* does not exist unless f is undoable"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["47c"]=window.LADDER_CARDS["47c"]||[]).push(
 {"u":"47c1.1","q":"What is a natural map α : F ⇒ G, and what does its square say? What does the square-in-a-row technique say, and which two squares does its proof spend?","a":"It gives each thing A of C an arrow α_A : F(A) → G(A) of D such that, for every arrow f : A → B, across by F(f) and down by α_B lands where down by α_A and across by G(f) lands; two natural maps run one after the other, at each thing, make a natural map; the proof spends β’s square and then α’s square","w":["It gives each arrow a thing; its square says F = G; the technique says natural maps cannot be run in a row","It is a statement that F forces G; its square says α_A = α_B; the proof spends one square twice","It gives one arrow for the whole category; the square says f is undoable; the proof spends the squares of F and G"],"why":"So maps of categories, with natural maps between them, are a category."},
 {"u":"47c2.1","q":"What is ev_V(v), and in which space does it live? What does the double-reading technique say, and which line of its proof uses a basis, and only to prove something, not to define ev?","a":"The reading of readings r ↦ r(v), which reads v by each reading; it lives in V**; reading a vector by every reading matches each space of finite dimension with its readings of readings, and the family of these matchings is natural; the last line, that ev_V is a matching, is the one that leans on a basis, through 27h1; ev itself was defined with no basis named","w":["The reading r(v), in k; the technique matches V with V*; the first line uses a basis to define ev","The vector v itself, in V; the technique says V** is larger than V; no line uses a basis","The basis of V, in V*; the technique says ev depends on the basis; every line uses one"],"why":"The square f** ∘ ev_V = ev_W ∘ f closes for every f."},
 {"u":"47c3.1","q":"What would it mean for a family of matchings V → V* to be carried along by every matching? What does the no-chosen-reading technique say, and which matching of the line breaks the family?","a":"That α_V(v)(u) = α_W(f(v))(f(u)) for all v, u and every matching f : V → W; over a field with more than three members, no family of matchings of each space of finite dimension with its readings is carried along by every matching; on the line k, the matching f(x) = t x with t ≠ 0 and t² ≠ 1 forces c = t²c for c = α_k(1)(1) ≠ 0, which cannot be","w":["That every α_V is the same grid; such a family exists over every field; the matching x ↦ −x breaks it","That α_V is linear; no family exists over any field, by the line with t = 1","That α_V keeps a basis; such a family exists once a basis is chosen; the matching x ↦ x + 1 breaks it"],"why":"Over ℝ, ℚ or ℂ take t = 2."},
 {"u":"47c4.1","q":"What is a natural matching of two maps of categories? What does the natural-undo technique say, and why does det pass the square for every ring map?","a":"A natural map α : F ⇒ G with every α_A undoable; if every arrow of a natural map can be undone, the undoings form a natural map back; det is a sum of products of entries, and a ring map keeps sums and products, so φ(ps − qr) = φ(p)φ(s) − φ(q)φ(r)","w":["A natural map with one α_A undoable; the undoings need not be natural; det passes because it is always 1","Any family of matchings; the undoings form a map of categories; det passes only for undoable ring maps","A matching of C with D; the undoing is α again; det passes because matrices commute"],"why":"Rows (3, 5) and (1, 4) have det 7, which is 2 on the clock of 5, as the image’s det 12 is."},
 {"u":"47c5.1","q":"Why are V ≅ V* and V ≅ V** not equally natural, though both are matchings? What does ⇒ mean between two maps of categories, and what does it not mean?","a":"Natural is the square, and only ev, the matching with V**, passes it; and between maps of categories ⇒ joins them as a natural map: it does not say that F forces G","w":["They are equally natural; and ⇒ means F forces G","Because V* is larger than V; and ⇒ means F equals G","Because V** needs a basis; and ⇒ means G is undoable"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["47d"]=window.LADDER_CARDS["47d"]||[]).push(
 {"u":"47d1.1","q":"What is a product of A and B, by its arrows alone? What does the pair-map technique say, and which technique of 2h gives the “exactly one”?","a":"A thing P with arrows p₁ : P → A and p₂ : P → B such that for every thing X and arrows f : X → A and g : X → B there is exactly one arrow u : X → P with p₁ ∘ u = f and p₂ ∘ u = g; in Set the set of pairs A × B, with the maps to the first and the second entry, is a product; reading a pair back (2h4): a pair is fixed by its two entries, so u(z) can only be (f(z), g(z)), the pair-function technique","w":["A thing with arrows from A and from B; the pair-map technique says A ∪ B is a product; the sift of 2e gives the “exactly one”","Any thing with an arrow to A and one to B; the pair-map technique says A × B has more members than A; nothing gives “exactly one”","The set of functions from A to B; the pair-map technique says pairs are matched with functions; the smallest sameness relation gives it"],"why":"Among statements the product of P and Q is P ∧ Q."},
 {"u":"47d2.1","q":"What does the one-matching technique say about two products of A and B? Which line of its proof uses “exactly one” on P itself, and what does it force?","a":"If P and P′ are both products of A and B, exactly one arrow from P′ to P agrees with the arrows out, and that arrow is a matching; the line u ∘ u′ = id_P: exactly one arrow P → P runs p₁ and p₂ through P, and both u ∘ u′ and id_P do, so they are forced to be the same arrow","w":["Two products are equal; the first line uses “exactly one”, and it forces P = P′","Two products are matched in many ways; no line uses “exactly one” on P","Two products need not be matched; the last line uses it, and forces u = u′"],"why":"That trick is the whole engine of the rung."},
 {"u":"47d3.1","q":"What is a sum of A and B, and how is it a product turned round? What does the cases-map technique say, and what are the sums of P and Q, and of nothing at all, among statements?","a":"A thing S with arrows i₁ : A → S and i₂ : B → S such that for every X and arrows f : A → X and g : B → X there is exactly one u : S → X with u ∘ i₁ = f and u ∘ i₂ = g: a product in the category with its arrows turned round; in Set two copies side by side, A ⊔ B, with each member sent to its copy, is a sum, a function out of it being a function on A and one on B taken case by case; among statements the sum of P and Q is P ∨ Q, and the sum of nothing is ⊥","w":["A thing with arrows to A and to B; the cases-map technique says A × B is a sum; the sum of P and Q is P ∧ Q, and of nothing is true","The union A ∪ B always; the cases-map technique says the union is a sum; the sum of P and Q is P ⇒ Q, and of nothing is P","The set of functions from A to B; the cases-map technique counts them; statements have no sums"],"why":"In Grp the sum of ℤ and ℤ is the free group on two letters, not ℤ × ℤ."},
 {"u":"47d4.1","q":"Why is A ∪ B not a sum of A and B in Set when A and B share a member? Why does the one-matching technique give matched products and not equal ones?","a":"On a shared member f and g may disagree, and then no u exists, which is why the copies are kept apart; and the property names no members: it gives products matched in exactly one way that agrees, and cannot give rung 0’s sameness","w":["A ∪ B is a sum always; and the technique gives equal products","Because A ∪ B is too large; and matched means equal","Because A ∪ B has no arrows; and products are never matched"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["47e"]=window.LADDER_CARDS["47e"]||[]).push(
 {"u":"47e1.1","q":"What are a shape, a picture, a cone and a limit? What does the sift-meets technique say, and what is the meeting place of a linear map and 0?","a":"A shape is a category J with few things; a picture of shape J in C is a map of categories D : J → C; a cone over D is a thing L with an arrow to each D(j), agreeing with every arrow of the picture; a limit is a cone through which every cone runs by exactly one arrow that agrees; in Set the sift of A where f and g agree, with its members sent to themselves, is a meeting place of f and g; for a linear map and 0 it is the kernel, what the map loses","w":["A shape is a space; a picture is a function; a cone is a product; a limit is the largest cone; the sift-meets technique says f = g; the meeting place is the image","A shape is a set; a picture is its sift; a cone is any thing; a limit is any cone; the meeting place of f and 0 is 0","A shape is an order; a cone is an arrow out of the picture; a limit is a sum; the meeting place is the whole space"],"why":"So the sift of 2e is a limit."},
 {"u":"47e2.1","q":"What is a forcing place of two parallel arrows, and how is it a limit turned round? What does the classes-force technique say, and which technique of 5·cb2 makes u well named?","a":"A thing Q with q : B → Q and q ∘ f = q ∘ g, through which every such arrow runs in exactly one way: the colimit of the two parallel arrows, a limit in the category turned round; in Set the classes of the smallest sameness relation that puts f(x) with g(x), each member sent to its class, are a forcing place, so a function out of the classes is a function on B that is constant on each class; the well-defined-function technique","w":["A thing with an arrow to A; it is a product; the classes-force technique says every function on B passes to the classes; the cancel technique","The sift where f and g agree; it is a limit as it stands; the technique says classes are sifts; the pair-function technique","A sum of A and B; the technique says the classes are A ⊔ B; the one-identity technique"],"why":"The integers of 5b are a forcing place of pairs."},
 {"u":"47e3.1","q":"What is the colimit of A ← C → B, and how is it built in Set? What does the glued-is-colimit technique say, and what does a continuous map out of the glued space amount to?","a":"A and B glued along C: a thing G with i₁ : A → G, i₂ : B → G and i₁ ∘ j = i₂ ∘ k, through which every such pair runs in exactly one way; in Set it is A ⊔ B with each j(c) put with k(c), a sum and then classes; the space glued from A and B along C is the colimit of the shape in Top, so a continuous map out of it is a pair of continuous maps on A and B that agree on C","w":["The product A × B; in Set it is the pairs; a continuous map out of the glued space is any function","The part C alone; in Set it is the sift; a continuous map out of it is a map on C","The union with C removed; in Set it is classes and then a sum of the classes; a continuous map out is a map on A only"],"why":"The figure eight is two circles glued along a point."},
 {"u":"47e4.1","q":"Why is the set of pairs (f(x), g(x)) not enough to give the classes of a forcing place? Why is a function on ℕ × ℕ not always a function out of ℤ?","a":"That set of pairs need not be a sameness relation, so the smallest sameness relation holding it is meant; and only a function constant on each class is one out of ℤ: (0, 1) and (1, 2) are one integer","w":["It is enough; and every function on ℕ × ℕ is one out of ℤ","Because the pairs are too many; and ℤ is larger than ℕ × ℕ","Because f and g are not onto; and functions on pairs are never constant"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["47f"]=window.LADDER_CARDS["47f"]||[]).push(
 {"u":"47f1.1","q":"What does F ⊣ U say about the arrows out of F(A) and the arrows into U(B)? What does the free-forgetful technique say, and how many product-keeping maps run from the free group on two letters to S₃?","a":"That for every A and B the arrows from F(A) to B are matched with the arrows from A to U(B), by matchings natural in A and in B; product-keeping maps from the free group on S to a group G match with functions from S to the members of G, by keeping only where the letters go, naturally; for two letters and S₃ there are 6² = 36","w":["That F undoes U; the technique says every function is product-keeping; there are 6 maps","That F(A) = U(B); the technique matches groups with sets; there are 2⁶ = 64 maps","That arrows into F(A) match arrows out of U(B); the technique says the free group is S; there are 12 maps"],"why":"One map for each choice of where x and y go."},
 {"u":"47f2.1","q":"What is ĥ for a function h of a pair, and what is its value at x? What does the pair-to-function technique say, and which power technique of rung 4 does it match, set for set?","a":"ĥ : A → D^B, and its value at x is the function y ↦ h(x, y): fix the first input, and what is left is a function of y; a function from A × B to D matches with a function from A to the functions from B to D, so taking pairs with B is left of taking functions from B; it matches 4g’s (dᵇ)ᵃ = d^(ab)","w":["ĥ is h undone, with value the pair (x, y); the technique says pairs are functions; it matches dᵃ · dᵇ = d^(a+b)","ĥ : B → A, with value x; the technique says functions from B are left of pairs; it matches (ab)ᵈ = aᵈbᵈ","ĥ is h with its inputs swapped; the technique says A × B = B × A; it matches d⁰ = 1"],"why":"For sizes 2, 3 and 2, both sides are 64."},
 {"u":"47f3.1","q":"What does an adjunction between two orders say? What does the fixing technique say, and what are H← and M→ for 46d’s field and group?","a":"Only that f(x) ≤ y exactly when x ≤ g(y); for any relation between two sets, B ⊆ A→ exactly when A ⊆ B←, so the two maps are an adjunction between the parts of X and the parts of Y turned round, with A ⊆ A→← and A→←→ = A→; H← is the field fixed by H, and M→ is the subgroup that fixes M","w":["That f and g undo each other; the technique says A→← = A always; H← is H’s quotient and M→ is M’s degree","That f(x) = g(x); the technique says every relation is an order; H← is the largest subgroup and M→ the smallest field","That f keeps order and g does not; the technique says A→ ⊆ A; H← is the centre of H and M→ is the splitting field of M"],"why":"46d’s correspondence is the further fact that every subgroup and middle field is closed."},
 {"u":"47f4.1","q":"What does the left-keeps-sums technique say? Why is the free group on two letters the sum of two copies of ℤ in Grp, and why does forgetting not carry that sum to a sum of sets?","a":"If F is left of U, F carries a sum of A and A′ to a sum of F(A) and F(A′); freeing is left of forgetting, so the free group on {x} ⊔ {y} is the sum of the free groups on {x} and on {y}, each of which is ℤ; forgetting is on the right and carries products, not sums: the members of the sum of ℤ and ℤ are words, not two copies side by side","w":["A left map carries products to products; the free group on two letters is ℤ × ℤ; forgetting carries every sum to a sum","A right map carries sums; the free group on two letters is ℤ; forgetting has no values on sums","Every map of categories carries sums; the free group is a sum because it has two members; forgetting fails because groups are not sets"],"why":"34i3’s figure eight, found with no picture."},
 {"u":"47f5.1","q":"Why does F ⊣ U not give U ⊣ F? Why is A→← not always A? Give the example on the page in your own words.","a":"Left and right differ: freeing keeps sums, forgetting keeps products, and neither keeps both; and A→← is A only for the closed parts: for the relation ≤ on the fractions, the part of fractions below 0 closes to the fractions at or below 0, one member more","w":["It does give U ⊣ F; and A→← is always A","Because U is not a map of categories; and A→← is always empty","Because F has no undoing; and the part {0} closes to all the fractions"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["47g"]=window.LADDER_CARDS["47g"]||[]).push(
 {"u":"47g1.1","q":"What is h_A(X), and what does h_A do to an arrow f : Y → X? What does the arrows-from-one technique say, and how is a real’s cut the arrows into it?","a":"The set C(X, A) of arrows from X into A; h_A(f) sends u : X → A to u ∘ f : Y → A, running f first, so h_A turns arrows round; in Grp the product-keeping maps from ℤ into G match with the members of G, by sending each map to where it sends 1; in an order the arrows into y are the things below y, and the fractions below a real are its cut","w":["The arrows out of A; h_A(f) sends u to f ∘ u; maps from ℤ into G match with the part-groups of G; a cut is the arrows out of a real","The members of A; h_A drops f; maps from ℤ into G number one; a cut is the real’s decimals","The things matched with A; h_A(f) is f undone; maps into ℤ match with members of G; a cut is the fractions above it"],"why":"ℤ is the free group on one letter."},
 {"u":"47g2.1","q":"What does a natural map from h_A to F give at each thing X? What does the arrows-into technique say, and why is the do-nothing arrow of A enough to fix α everywhere?","a":"A function α_X from the arrows X → A to F(X), with α_Y(u ∘ f) = F(f)(α_X(u)); a natural map from the arrows into A to F is fixed by where it sends the do-nothing arrow of A, and every member of F(A) is where exactly one natural map sends it; every arrow u into A is id_A run after u, so the square gives α_X(u) = F(u)(α_A(id_A))","w":["An arrow X → A; the technique says there is one natural map in all; id_A is enough because it is the only arrow into A","A member of A; the technique says natural maps match with arrows out of A; id_A fixes α because α is undoable","A function from F(X) to A; the technique says no natural maps exist unless F = h_A; id_A is not enough"],"why":"So the natural maps from h_A to F are matched with F(A)."},
 {"u":"47g3.1","q":"What does the known-by-arrows technique say? How does it give 47d2’s one-matching technique for products?","a":"If the arrows into A and the arrows into B are naturally matched, A and B are matched, by the arrow the matching sends id_A to; a product is a thing whose arrows into it from each X are naturally matched with pairs of arrows X → A, X → B, so two products have naturally matched arrows into them and are matched","w":["If A and B have the same members they are matched; products are matched because they are sets of pairs","If h_A(X) and h_B(X) are matched for one X, then A ≅ B; products are equal","If A ≅ B then h_A = h_B; it says nothing about products"],"why":"Two reals with the same fractions below them are the same real."},
 {"u":"47g4.1","q":"Why does a matching of h_A(X) with h_B(X) for each X separately not give A ≅ B? Why do the maps from ℤ alone not tell S₃ from ℤ/6?","a":"The matchings must be natural: a family chosen thing by thing need not close the squares; and arrows from ℤ alone see only the members, and S₃ and ℤ/6 both have six","w":["It does give A ≅ B; and the maps from ℤ do tell them apart","Because h_A(X) is never a set; and ℤ has no maps to S₃","Because A and B must be equal; and S₃ has more members than ℤ/6"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["47h"]=window.LADDER_CARDS["47h"]||[]).push(
 {"u":"47h1.1","q":"What is a map straight in each slot, and what property makes T a tensor product of V and W? What does the grid-space technique say, and why is the dimension of ℝ² ⊗ ℝ³ not 5?","a":"A map β from V × W that is straight in v with w held and in w with v held; T, with a map ⊗ : V × W → T straight in each slot, is a tensor product when every such β runs through it as exactly one linear map β̄ with β̄(v ⊗ w) = β(v, w); the space with basis the mn symbols eᵢ ⊗ f_j, and v ⊗ w = Σ vᵢ w_j eᵢ ⊗ f_j, is a tensor product, so V ⊗ W has dimension mn; 5 = 2 + 3 is the dimension of the product ℝ² × ℝ³, and the tensor product has 2 · 3 = 6","w":["A linear map of V × W; T is a tensor product when it is the pairs; the grid-space technique gives dimension m + n; ℝ² ⊗ ℝ³ has dimension 5","A map straight in v only; T is a tensor product when some β runs through it; the dimension is the larger of m and n, here 3","A map with β(v, w) = β(w, v); T is a tensor product when ⊗ is one-to-one; the dimension is 2³ = 8"],"why":"Readings straight in each slot are the readings of V ⊗ W."},
 {"u":"47h2.1","q":"Why is the grid of v ⊗ w of rank at most 1? What does the fewest-terms technique say, and why is e₁ ⊗ f₁ + e₂ ⊗ f₂ no single v ⊗ w?","a":"It is the grid v wᵀ, every row a multiple of wᵀ, so what it reaches lies along one arrow; a member of V ⊗ W is a sum of r terms v ⊗ w, and of no fewer, exactly when its grid has rank r; e₁ ⊗ f₁ + e₂ ⊗ f₂ has the grid with rows (1, 0) and (0, 1), of rank 2","w":["Because v and w are unit arrows; every member is a single v ⊗ w; e₁ ⊗ f₁ + e₂ ⊗ f₂ is (e₁ + e₂) ⊗ (f₁ + f₂)","Because its grid is square; a member needs mn terms always; the sum has rank 0","Because its determinant is 1; the fewest terms is the dimension of V; the sum is no v ⊗ w because it is not in V ⊗ W"],"why":"The members of rank above 1 are the ones physics calls entangled."},
 {"u":"47h3.1","q":"What does the coprime-clocks technique say, and which two facts about the clocks does its proof spend? When is a row of maps exact at a place, and what goes wrong with 0 → ℤ → ℤ → ℤ/2 → 0 tensored with ℤ/2?","a":"Over the whole numbers, the clock of two tensored with the clock of three is nothing; the proof spends 2g = 0 on the clock of 2 and 3h = 0 on the clock of 3, with 3 − 2 = 1; a row A → B → C is exact at B when what the first map reaches is exactly what the second loses; tensored with ℤ/2, doubling becomes 0, so the first map, once one-to-one, loses everything, and the row is no longer exact at its start","w":["The clock of two tensored with the clock of three is the clock of six; it spends that 2 and 3 are prime; a row is exact when every map is onto; nothing goes wrong","ℤ/2 ⊗ ℤ/3 has six members; it spends 2 + 3 = 5; a row is exact when the maps are undoable; tensoring breaks the row at its end","ℤ/2 ⊗ ℤ/3 is ℤ; it spends that 2 divides 6 and 3 divides 6; a row is exact when the maps are 0; the last map stops being onto"],"why":"Tensoring keeps a row exact at its end and can break it at its start."},
 {"u":"47h4.1","q":"Why is (v + v′) ⊗ (w + w′) not v ⊗ w + v′ ⊗ w′? Why does 1 ⊗ 1 = 0 in ℤ/2 ⊗ ℤ/3 not mean that 1 is nothing on either clock?","a":"Straight in each slot gives four terms: v ⊗ w′ and v′ ⊗ w must be added; and g ⊗ h = 0 does not give g = 0 or h = 0: the whole tensor product is nothing, with neither 1 nothing","w":["It is equal; and 1 is nothing on both clocks","Because ⊗ is not straight; and 1 ⊗ 1 is not 0","Because v′ and w′ are 0; and 1 = 0 on the clock of 2"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["47i"]=window.LADDER_CARDS["47i"]||[]).push(
 {"u":"47i1.1","q":"What are the product and the sum of two numbers in the dividing order? Why is the “exactly one” part of the product property free in any order?","a":"The product is their greatest common divisor and the sum is the least number both divide: for 12 and 18, 6 and 36; in an order there is at most one arrow between two things, so an arrow that exists is the only one","w":["The product is m · n and the sum m + n: 216 and 30; “exactly one” is free because numbers are whole","The product is the least number both divide and the sum the greatest common divisor; “exactly one” is free because dividing is symmetric","The product is the smaller and the sum the larger; “exactly one” must be checked prime by prime"],"why":"1 has an arrow to every number and 0 has an arrow from every number."},
 {"u":"47i2.1","q":"What does the count-the-arrows technique say? How many product-keeping maps run from ℤ × ℤ to S₃, and from the sum of ℤ and ℤ, and what does the difference prove?","a":"If S is a sum of A and B, the number of arrows from S to X is the number from A to X times the number from B to X, for every X, so a thing whose counts disagree for one X is no sum; from ℤ × ℤ to S₃ there are 18, the pairs that change places, and from the sum 6 · 6 = 36; so ℤ × ℤ is no sum of ℤ and ℤ in Grp","w":["The arrows into a sum add; there are 12 maps from ℤ × ℤ and 12 from the sum; so ℤ × ℤ is the sum","The count from a sum is the count from A plus the count from B; 36 from ℤ × ℤ and 18 from the sum; so S₃ is not a group","Every thing with the right count is a sum; 36 and 36; the difference proves nothing"],"why":"Among turn-about groups ℤ × ℤ is the sum."},
 {"u":"47i3.1","q":"What does the no-common-field technique say? Which fact about ring maps does each of its two cases spend?","a":"No field has a ring map both to the clock of two and to the fractions, so the two have no product among fields; if 1 + 1 = 0 in P, the map to ℚ, keeping 1 and sums, gives 2 = 0 in ℚ; if not, 1 + 1 has a reciprocal u, and the map to ℤ/2, keeping products, gives φ(u) · 0 = 1 there","w":["Every two fields have a product, the pairs; the cases spend that ring maps are onto","No field has a ring map to ℚ; both cases spend that ring maps keep order","The clock of two and ℚ have the product ℤ; the cases spend that ring maps are one-to-one and undoable"],"why":"Fields keep whether 1 + 1 is 0."},
 {"u":"47i4.1","q":"Why does agreeing on the count for one X not prove that a thing is a sum? Why are pairs of members of two fields, with entrywise sums and products, not a field?","a":"Agreeing counts are not the property; only a disagreement for one X settles anything, by ruling a sum out; and (1, 0)(0, 1) = (0, 0): two pairs that are not 0 with product 0, so the pairs are a ring, not a field","w":["It does prove it; and the pairs are a field","Because counts are never equal; and the pairs have no 1","Because X must be a sum too; and the pairs cannot be added"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["47j"]=window.LADDER_CARDS["47j"]||[]).push(
 {"u":"47j1.1","q":"What are the typing techniques for λx. t, for t s, and for pairs? What does the typed-term technique say, and why has λx. x x no type?","a":"If, with x : A added, t : B, then λx. t : A → B; if t : A → B and s : A, then t s : B; if t : A and s : B, then ⟨t, s⟩ : A × B, and from p : A × B, fst p : A and snd p : B; λf. λx. f (f x) has type (A → A) → (A → A) for every type A, and applied to a function and an input it runs the function twice; in x x, x would need a type A equal to A → B, and no type built by the techniques is shorter than itself","w":["λx. t : B; t s : A → B; pairs have type A → B; the typed-term technique says every term has a type; λx. x x has type A → A","λx. t : A × B; t s : A; pairs have no type; the technique says λf. λx. f (f x) never stops; λx. x x has no type because x is used twice","λx. t : A; t s : B × A; a pair has the type of its first entry; the technique says the term runs f once; λx. x x has no type because it has no input"],"why":"Run on next and 3 it gives 5."},
 {"u":"47j2.1","q":"Which move of natural deduction does λx. t match, and which does t s match? What does the proofs-as-terms technique say, and what is the program that proves (P ∧ Q) ⇒ (Q ∧ P)?","a":"λx. t is the box: suppose A, reach B, write A ⇒ B and drop the supposition; t s is using an if: from A ⇒ B and A, B; a tree proof of B from suppositions, using only if and and, is a term of type B with placeholders of the suppositions’ types, and every such term is such a proof; the program is λp. ⟨snd p, fst p⟩, which swaps a pair","w":["λx. t is join and t s is keep either part; a proof is a type; the program is λp. p","λx. t is using an if and t s is the box; every term is a statement; the program is fst p","λx. t is cases and t s is add an option; a proof is a run that never stops; the program is ⟨p, p⟩"],"why":"A statement is true in this calculus when its type has a member."},
 {"u":"47j3.1","q":"What is a detour in a tree proof, and what term does it become? What does the detour-is-step technique say, and why does P ∨ ¬P have no term?","a":"A place where an if is built and at once used; as a term it is (λx. t) s; cutting a detour from a proof is one step of running its term: putting s in for x; P ∨ ¬P has no term because a program would have to decide, for an unknown P, which side it can produce","w":["A supposition never dropped; it becomes λx. x; cutting it adds a step; P ∨ ¬P has no term because it is false","A proof used twice; it becomes a pair; cutting a detour is typing the term; P ∨ ¬P has the term inl p","A join followed by a join; it becomes t s s; the technique says detours cannot be cut; P ∨ ¬P has no term because ¬ is not a type"],"why":"Straightening a proof is running a program."},
 {"u":"47j4.1","q":"Why has λx. x x no type? Why is P ∨ ¬P true in every row of 1e’s table and still without a term?","a":"x x needs x : A → B and x : A at once, and no type is both; and being true in every row is not having a term here: rung 7’s either-way is not a program, though ¬¬(P ∨ ¬P) is","w":["It has type A → A; and P ∨ ¬P has a term","Because x is not a placeholder; and P ∨ ¬P is false in one row","Because terms cannot be applied; and every true statement has a term"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["47·cb0"]=window.LADDER_CARDS["47·cb0"]||[]).push(
 {"u":"47·cb0.1.1","q":"What does x = y say, and what does A ≅ B say, and why does the swap not run across A ≅ B? What does the arrow-counts-kept technique say, and how does it tell ℤ/6 from S₃?","a":"x = y says one thing has two names; A ≅ B says an undoable arrow runs from A to B; {1, 2} and {3, 4} are matched, and 1 ∈ {1, 2} is true while 1 ∈ {3, 4} is false, so not every statement crosses a matching; if A and B are matched, then for every X the arrows from X into A are matched with those into B, and those out of A with those out of B; from ℤ × ℤ there are 18 maps into S₃ and 36 into ℤ/6, so the two are not matched in Grp","w":["Both say the same; the swap runs across ≅; the technique says matched things have equal members; ℤ/6 and S₃ are matched","x = y says two things are matched; A ≅ B says they are one; the technique counts members: 6 and 6, so they differ","x = y says x and y have an arrow; A ≅ B says they share members; the technique says arrows are not kept; ℤ/6 has more members"],"why":"A matching tells exactly what arrows can see."},
 {"u":"47·cb0.2.1","q":"What is a counting run, and a map between two? What does the first-run technique say, and where does it send 3c’s 3?","a":"A set N with a member z and a function s : N → N; a map of counting runs to (M, y, t) is a function f with f(z) = y and f ∘ s = t ∘ f; any two counting runs with the recursion property are matched by exactly one map that keeps the start and the next; it sends {∅, {∅}, {∅, {∅}}} = {0, 1, 2} to {{{∅}}} = {2}, the 3 of the gathering run","w":["A list of numbers; a map is any function; the technique says there is one counting run; 3 goes to 3","A set with an order; a map keeps order; the technique says two runs are matched in many ways; 3 goes to ∅","A function from ℕ to ℕ; a map is a product; the technique says runs are equal as sets; 3 goes to {0, 1, 2} again"],"why":"Exactly one matching, forced at every step."},
 {"u":"47·cb0.3.1","q":"Why is 1 + 2 = 3 true in both runs, and 1 ∈ 3 true in only one? What does the call back answer to “which set is three?”, and what of rung 0’s sameness does it keep?","a":"Adding is built by recursion from 0 and next, so the matching of the runs carries it, and every statement of counting true in one run is true in the other; ∈ is not a mark of counting, the matching does not carry it, and 1 ∈ {0, 1, 2} is true while 1 ∈ {2} is false; three is the place after the place after the place after the start in the first counting run, and which set sits there is the build’s business; rung 0’s sameness is kept: it still says a thing is itself","w":["Both are true in both runs; three is the set {0, 1, 2} and no other; rung 0’s sameness is given up","1 + 2 = 3 is true in one run only; three is whatever set has three members; sameness now means equal sizes","Neither is a statement of counting; three is no set at all and names nothing; rung 0’s sameness is replaced by matching"],"why":"A statement true in one run and false in the other speaks of the build."},
 {"u":"47·cb0.4.1","q":"Why does A ≅ B and P(A) not give P(B) for every P? Why does the gathering run have the recursion property, though its next forgets the members of x?","a":"Only for P made of arrows: the swap runs across =, not ≅; and recursion needs a one-to-one next, a start that is no next, and smallness, and {x} has all three","w":["It does give P(B); and the gathering run has no recursion","Because P is never about arrows; and its next is onto","Because A and B have different sizes; and the gathering run is the next-one run"],"why":"Both are rows of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["47·eng"]=window.LADDER_CARDS["47·eng"]||[]).push(
 {"u":"47·eng.1.1","q":"What does the row-of-boxes technique say, and why does the bracketing of a chain not matter? Run the two stages above in the other order. Does the transfer change?","a":"Two parts with transfers H₁ and H₂, run in a row, make one part with transfer H₂H₁, so a chain of parts is one part; the transfers are numbers at each frequency, and multiplying numbers can be bracketed either way; in the other order the transfer is H₁H₂ = 1/((1 + 2πiξ)(4 + 2πiξ)), the same, since numbers commute","w":["The transfers add, H₁ + H₂; bracketing matters; in the other order the transfer doubles","The transfer of a row is the larger of the two; bracketing does not matter because both are 1; the other order gives 1/H","The transfers divide, H₂/H₁; the other order gives H₁/H₂, a different part"],"why":"|H(0)| = 1/4 and |H(1)| ≈ 0.021."},
 {"u":"47·eng.2.1","q":"What does the box-drawing technique say, and why do the 0 blocks matter in its proof? For the stereo above, what is the transfer of the right channel, and what does the left channel do to the right?","a":"A drawing of parts in rows and side by side names one part whether read row by row or column by column: (g ∘ f) ⊕ (g′ ∘ f′) = (g ⊕ g′) ∘ (f ⊕ f′); grids in blocks multiply block by block, and the 0 corner blocks give 0 into the rest, so no cross terms appear; the right channel’s transfer is 3H₂ = 3/(4 + 2πiξ), and the left channel does nothing to the right: the corners are 0","w":["Side by side parts multiply; the 0 blocks make the grid undoable; the right channel has transfer 2H₁, and the left adds to it","Rows and columns of a drawing give different parts; the 0 blocks do not matter; the right channel has transfer H₂ alone","A drawing must be read row by row; the 0 blocks stand for silence; the right channel has transfer 6H₁H₂"],"why":"For qubits side by side means the tensor product; the drawing must say which."},
 {"u":"47·eng.3.1","q":"What does the loop-closing technique say, and why does the whole come out near 1/H when GH is large? With H = 0.1, what is the whole for G = 1000 and for G = 2000?","a":"A part G whose output is fed back through H and taken from the input is one part with transfer G/(1 + GH), wherever 1 + GH is not 0; for GH large, 1 + GH is nearly GH, so G/(1 + GH) is near G/(GH) = 1/H; with H = 0.1 the whole is 1000/101 ≈ 9.90 for G = 1000 and 2000/201 ≈ 9.95 for G = 2000","w":["The whole is G + H; it is near 1/H because G cancels; 1000.1 and 2000.1","The whole is GH; it is near 1/H when G is small; 100 and 200","The whole is G/(1 − GH); it is near −1/H; about −10.1 and −10.05, twice as far apart as the open parts"],"why":"Doubling G moves the whole by half a percent."},
 {"u":"47·eng.4.1","q":"What does the loading technique say, and which part of the proof shows the second stage changing the first? If the second divider is made of resistors of 100R, what does the pair send V to, to three places?","a":"Two halving dividers of equal resistors R, the second fed from the middle of the first, send V to V/5, not V/4: a part is an arrow on voltages only while what it drives draws no current; the second stage, 2R, sits side by side with the first’s lower R and makes it 2R/3, so the first’s middle is at 2V/5, not V/2; with 100R, the lower half is 200R/201, the middle is at 200V/401, and the pair sends V to 100V/401 ≈ 0.249 V","w":["Two dividers give V/4 always; nothing changes the first stage; with 100R the pair gives 0.200 V","Two dividers give V/2; the first stage changes the second; with 100R the pair gives 0.500 V","Two dividers give V/5 for any resistors; the proof shows the current is 0; with 100R the pair gives exactly 0.250 V"],"why":"The lighter the load, the nearer the quarter."},
 {"u":"47·eng.5.1","q":"What does the chain-grid technique carry that the loading technique’s voltages did not, and why do its grids multiply with no loading left over? Find D³ and the far voltage of three halving dividers in a row.","a":"It carries the pair (V, I), the current as well as the voltage; each part takes the pair the next part hands back, so whatever current the next part draws is already in what is passed, and the grids multiply exactly; D³ has rows (13, 8R) and (8/R, 5), so with nothing drawn at the far end the far voltage is V/13","w":["It carries the frequency; grids multiply because resistors are equal; D³ has top left 8, so V/8","It carries the power; the grids add; D³ has rows (6, 3R) and (3/R, 3), so V/6","It carries the voltage twice; loading is ignored; D³ has top left 125, so V/125"],"why":"D² has rows (5, 3R) and (3/R, 2): the loading technique’s fifth."},
 {"u":"47·eng.6.1","q":"Someone wires two filters in a row, measures each alone, and multiplies the two transfers to predict the whole. When is that prediction right, and what would you measure to check it?","a":"It is right only when the second filter draws no current from the first, so that what passes along the wire is all each part depends on, as with a follower between them; to check, measure the first filter’s output with the second connected and compare it with its output alone, or carry voltage and current together and multiply the chain grids","w":["It is always right, since transfers are numbers; nothing need be measured","It is never right; measure the frequency of the input","It is right when the filters are equal; measure the second filter alone again"],"why":"A row of the step’s Moves to Watch Out For."});
(window.LADDER_CARDS["47·phys"]=window.LADDER_CARDS["47·phys"]||[]).push(
 {"u":"47·phys.1.1","q":"What does the face-and-axis technique say each grid reads? For the wheel above, what is the rotational inertia about the axis along (0, 0, 1)?","a":"The stress grid read on two vectors of length 1, mᵀσn, is the push along m on the cut facing n; the inertia grid read twice on one vector u of length 1, uᵀΘu, is the rotational inertia about the axis along u; for u = (0, 0, 1) it is the bottom right entry, 0.04 kg m²: each lump is √0.02 m from that axis, and 2 · 1 · 0.02 = 0.04","w":["The stress grid reads a length and the inertia grid a speed; about (0, 0, 1) the inertia is 0.02 kg m²","Both read the determinant; about (0, 0, 1) the inertia is 0","The stress grid reads the push on a cut facing m along n only when m = n; the inertia is −0.02 kg m²"],"why":"Each grid is one reading of ℝ³ ⊗ ℝ³."},
 {"u":"47·phys.2.1","q":"Why does a vector’s list become Qᵀx and not Qx when the axes turn to the columns of Q? A stress has the grid with rows (3, 0) and (0, 1). What is its grid on axes turned by 45°?","a":"The old list is the new list spread along the columns of Q, x = Qx′, and Q is undone by Qᵀ, so x′ = Qᵀx; the grid becomes QᵀσQ, with rows (2, −1) and (−1, 2)","w":["Because Q is symmetric; the grid stays (3, 0), (0, 1)","Because the vector turns with the axes, x′ = Qx; the grid becomes (1, 0), (0, 3)","Because Qᵀ = Q; the grid becomes (2, 1), (1, −2)"],"why":"The stretches are still 3 and 1."},
 {"u":"47·phys.3.1","q":"What does the square-the-space technique say, and why must the technique for two turnings in a row agree with the technique for the single turn Q₁Q₂? Why does “1 in the top left corner on any axes” describe no stress?","a":"Sending each space V to V ⊗ V and each straight map f to f ⊗ f is a map of categories: (g ∘ f) ⊗ (g ∘ f) = (g ⊗ g) ∘ (f ⊗ f), and the do-nothing map goes to the do-nothing map; so the technique respects running in a row, and turning by Q₁ and then Q₂ gives (Q₁Q₂)ᵀG(Q₁Q₂), the grid of the one turn; a quarter turn sends the grid with 1 in the top left to the one with 1 in the bottom right, against the claim, so the technique describes no sheet","w":["V ⊗ V is V × V; two turnings need not agree with one; “1 in the corner” is a stress on every axes","f ⊗ f = f + f; the techniques agree because turnings commute; “1 in the corner” fails because 1 is too small","Sending V to V ⊗ V turns arrows round; two turnings give the grid of Q₂Q₁; “1 in the corner” is a pure shear"],"why":"A grid of measurements is a tensor exactly when its numbers change by the new-axes technique."},
 {"u":"47·phys.4.1","q":"What does the same-on-every-axes technique say is kept when the axes turn? A sheet has σ with rows (2, 1) and (1, 2). What are its principal stresses, and is it a single pull?","a":"QᵀGQ has the same stretches as G and the same rank, so the principal stresses, the principal inertias and the rank of a reading of two vectors are the same on every axes; the stretches of that σ are 3 and 1, along (1, 1) and (1, −1), so its rank is 2 and it is not a single pull","w":["The entries of the grid are kept; the principal stresses are 2 and 2; it is a single pull","Only the top left entry is kept; the principal stresses are 2 and 1; it is a single pull along (2, 1)","Nothing is kept; the principal stresses depend on the axes; it has rank 1"],"why":"A rope in tension carries a stress of rank 1."},
 {"u":"47·phys.5.1","q":"Someone says “a tensor is just a matrix.” Using the new-axes technique and the square-the-space technique, say what is missing from that line.","a":"A grid is a tensor written on one choice of axes; what is missing is the technique for how the writing changes, QᵀGQ when the axes turn to the columns of Q, and that the technique respects turnings run in a row, which is the same as the grid being one member, or one reading, of a tensor product","w":["Nothing is missing: any grid of measured numbers is a tensor","That a tensor must be symmetric and of rank 1","That a tensor’s numbers must be the same on every axes"],"why":"A row of the step’s Moves to Watch Out For."});
